package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.protocol.*;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.sources.*;import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;import com.lianxibu.site.repository.identity.*;import com.lianxibu.site.service.identity.*;import com.lianxibu.site.service.jobs.*;
import java.time.*;import java.util.*;import javax.sql.DataSource;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import tools.jackson.databind.node.ObjectNode;
class SourceContractFactsNativeTest {
 SourceContractSnapshotServiceTest f;JdbcSourceContractFacts facts;String actor,second;Instant at;
 DataSource source(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:source-facts-"+System.nanoTime()+";MODE=MySQL;DB_CLOSE_DELAY=-1");return ds;}
 @BeforeEach void setup(){f=new SourceContractSnapshotServiceTest(){@Override DataSource source(){return SourceContractFactsNativeTest.this.source();}};f.setup();at=f.f.now;actor=UUID.randomUUID().toString();f.f.jdbc.execute("CREATE TABLE IF NOT EXISTS users(id VARCHAR(64) PRIMARY KEY,username VARCHAR(64),password_hash VARCHAR(255),revision BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP)");if(!(f.f.db instanceof JdbcDataSource))for(var col:Map.of("username","VARCHAR(64)","password_hash","VARCHAR(255)","revision","BIGINT","created_at","DATETIME(6)","updated_at","DATETIME(6)").entrySet())if(f.f.jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name=?",Integer.class,col.getKey())==0)f.f.jdbc.execute("ALTER TABLE users ADD COLUMN "+col.getKey()+" "+col.getValue()+" NULL");new JdbcPasswordAdminStore(f.f.db,f.clock).initialize(actor,"fictional-"+actor,"fictional-owned-password-hash");
  f.f.tx.execute(s->{assertTrue(f.sources.disable(f.sources.locked(f.sourceId),at));return null;});var config="{\"parser_version\":\"fictional-v1\",\"valid_until\":\"2026-01-01T01:10:00.000000Z\"}";f.f.jdbc.update("UPDATE sources SET config_json=?,draft_config_json=? WHERE id=?",config,config,f.sourceId);
  var row=f.f.tx.execute(s->f.sources.locked(f.sourceId));var proof=(ObjectNode)CanonicalJson.parse(new ManualSourceAdmissionTest(){{setup();}}.proof.toString());proof.put("action_key","fictional-approve-"+actor);proof.put("source_id",f.sourceId);proof.put("reviewer_id",actor);proof.put("expected_revision",row.revision());proof.put("config_version",row.configRevision());proof.put("config_sha256",SourceIdentityMappingService.sha256(row.draftConfigJson()));proof.put("legacy_config_sha256",SourceIdentityMappingService.sha256(row.legacyConfigJson()));proof.put("parser_version","fictional-v1");proof.put("reviewed_at",at.toString());proof.put("expires_at",at.plusSeconds(3600).toString());
  var manual=new ManualSourceAdmission(new JdbcManualSourceAdmissions(f.f.db),f.sources,new SharedWriteExecutor(new JdbcSharedWriteEntry(f.f.db),new DataSourceTransactionManager(f.f.db)),f.clock);assertEquals("production",manual.apply(new IdentityService.Actor(actor,"owner"),"approve",ManualSourceAdmission.Manifest.parse(CanonicalJson.bytes(proof))).activationStage());facts=new JdbcSourceContractFacts(f.f.db,new DataSourceTransactionManager(f.f.db),new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at;}});
 }
 @AfterEach void cleanup(){if(f!=null){if(second!=null)f.f.jdbc.update("DELETE FROM collector_nodes WHERE id=?",second);if(actor!=null)f.f.jdbc.update("DELETE FROM users WHERE id=?",actor);f.cleanup();}}
 void submit(long sequence,long total)throws Exception{var root=(ObjectNode)CanonicalJson.parse(f.raw(sequence));root.put("total_failures",total);if(total==0)root.putArray("events");f.service.submit(f.token,f.sourceId,CanonicalJson.bytes(root));}
 @Test void completeOriginalManualReceiptAndNativeZeroAreKnown()throws Exception{assertNull(facts.read(f.sourceId));submit(1,0);var value=facts.read(f.sourceId);assertNotNull(value);assertEquals(0,value.totalFailures());assertEquals(1,value.nodeCount());assertEquals(at,value.reviewedAt());assertEquals(at,value.observedAt());assertEquals(value,new JdbcSourceContractFacts(f.f.db,new DataSourceTransactionManager(f.f.db),f.clock).read(f.sourceId));}
 @Test void allExpectedNodesAreRequiredAndAnotherZeroCannotMaskFailure()throws Exception{submit(1,1);second=UUID.randomUUID().toString();f.nodes.create(second,"Fictional second",NodeTokens.digest("fictional-second-token"),"[\""+f.sourceId+"\"]","[\"heartbeat:write\"]");assertNull(facts.read(f.sourceId));var input=f.f.value(1,0,false);var root=(ObjectNode)CanonicalJson.parse(input.canonical());root.put("source_id",f.sourceId);f.f.tx.execute(s->f.f.store.save(second,1,SourceContractTelemetry.parse(CanonicalJson.bytes(root)),at));var value=facts.read(f.sourceId);assertNotNull(value);assertEquals(2,value.nodeCount());assertEquals(1,value.totalFailures());assertEquals(1,value.eventsInWindow());String epoch=value.resourceEpoch();assertEquals(1,f.nodes.revoke(second,1));assertNotEquals(epoch,facts.read(f.sourceId).resourceEpoch());}
 @Test void staleCurrentNodeConfigMissingPermissionOrBadReceiptNeverBecomeZero()throws Exception{submit(1,0);assertNotNull(facts.read(f.sourceId));at=at.plusSeconds(121);assertNull(facts.read(f.sourceId));at=f.f.now;assertEquals(1,f.nodes.rotate(f.nodeId,1,NodeTokens.digest("fictional-rotated")));assertNull(facts.read(f.sourceId));f.f.jdbc.update("UPDATE collector_nodes SET config_revision=1,permissions_json='[]' WHERE id=?",f.nodeId);assertNull(facts.read(f.sourceId));f.f.jdbc.update("UPDATE collector_nodes SET permissions_json='[\"heartbeat:write\"]' WHERE id=?",f.nodeId);f.f.jdbc.update("UPDATE request_receipts SET request_hash=? WHERE scope='source-contract-telemetry-v1'",new byte[32]);assertNull(facts.read(f.sourceId));}
 @Test void sourceConfigExpiryOrOriginalApprovalProofDamageIsUnknown()throws Exception{submit(1,0);assertNotNull(facts.read(f.sourceId));f.f.jdbc.update("UPDATE request_receipts SET business_hash=? WHERE scope='manual-source-admission-v1'",new byte[32]);assertNull(facts.read(f.sourceId));}
 @Test void sourceWideNativeCapacityMissingAdmissionAndOutsideTxStayUnknown()throws Exception{submit(1,0);assertNotNull(facts.read(f.sourceId));assertThrows(IllegalStateException.class,()->f.f.tx.execute(s->facts.read(f.sourceId)));f.f.jdbc.update("UPDATE sources SET effective_config_json=? WHERE id=?","{\"parser_version\":\"fictional-v1\",\"extra\":\""+"x".repeat(65536)+"\"}",f.sourceId);assertNull(facts.read(f.sourceId));assertNull(facts.read("fictional-missing"));}
}
